}

input.new_string:
/**
 * The rollup job's work list: live workspaces whose counters were recounted
 * longest ago, at most `limit` of them.
 *
 * `measured_at` advances only on a full recount (`recomputeUsage`). The cheap
 * deltas from creates and deletes leave it alone, so they do not change a
 * workspace's place. A missing usage row sorts first (never recounted).
 * Deleted workspaces are omitted.
 */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizations.id })
    .from(organizations)
    .leftJoin(organizationUsage, eq(organizationUsage.orgId, organizations.id))
    .where(isNull(organizations.archivedAt))
    .orderBy(asc(organizationUsage.measuredAt), asc(organizations.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

/**
 * Stamp that sorts after every `measured_at` already stored. Uses the clock
 * when it is already ahead, otherwise one millisecond past the current max,
 * so a recounted workspace moves to the back of the queue even if several
 * recounts share the same instant.
 */
function nextRecountStamp(): ReturnType<typeof toIsoTimestamp> {
  const latest = getDb()
    .select({ value: sql<string | null>`max(${organizationUsage.measuredAt})` })
    .from(organizationUsage)
    .get();

  const nowDate = new Date();
  const maxAt = latest?.value ?? null;
  if (maxAt !== null) {
    const maxTime = new Date(maxAt).getTime();
    if (Number.isFinite(maxTime) && nowDate.getTime() <= maxTime) {
      return toIsoTimestamp(new Date(maxTime + 1));
    }
  }
  return toIsoTimestamp(nowDate);
}

