/**
 * Stamp that sorts after every `measured_at` already stored. Uses the clock
 * when it is already ahead, otherwise one millisecond past the current max,
 * so a recounted workspace moves to the back of the queue even if several
 * recounts share the same instant.
 */
function nextRecountStamp(): ReturnType<typeof toIsoTimestamp> {
  const latest = getDb()
    .select({ value: sql<string | null>`max(${organizationUsage.measuredAt})` })
    .from(organizationUsage)
    .get();

  const nowDate = new Date();
  const maxAt = latest?.value ?? null;
  if (maxAt !== null) {
    const maxTime = new Date(maxAt).getTime();
    if (Number.isFinite(maxTime) && nowDate.getTime() <= maxTime) {
      return toIsoTimestamp(new Date(maxTime + 1));
    }
  }
  return toIsoTimestamp(nowDate);
}
